import{_ as l,o as s,c as r,ah as n}from"./chunks/framework.DjU4PSOm.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 주의사항","slug":"_1-주의사항","link":"#_1-주의사항","children":[{"level":3,"title":"Robots.txt의 개념과 경로","slug":"robots-txt의-개념과-경로","link":"#robots-txt의-개념과-경로","children":[]},{"level":3,"title":"수집 및 관리 시 핵심 주의 사항","slug":"수집-및-관리-시-핵심-주의-사항","link":"#수집-및-관리-시-핵심-주의-사항","children":[]}]},{"level":2,"title":"2. 웹 크롤링 vs 웹 스크래핑","slug":"_2-웹-크롤링-vs-웹-스크래핑","link":"#_2-웹-크롤링-vs-웹-스크래핑","children":[{"level":3,"title":"2. 정적 웹페이지 vs 동적 웹페이지","slug":"_2-정적-웹페이지-vs-동적-웹페이지","link":"#_2-정적-웹페이지-vs-동적-웹페이지","children":[]},{"level":3,"title":"3. 스크래핑 핵심 도구 및 개념","slug":"_3-스크래핑-핵심-도구-및-개념","link":"#_3-스크래핑-핵심-도구-및-개념","children":[]}]}],"relativePath":"computer/project/imfoster/02. 웹 스크래핑과 HTML 이해하기.md","filePath":"computer/project/imfoster/02. 웹 스크래핑과 HTML 이해하기.md"}'),o={name:"computer/project/imfoster/02. 웹 스크래핑과 HTML 이해하기.md"};function e(a,t,i,p,d,g){return s(),r("div",null,[...t[0]||(t[0]=[n(`<h2 id="_1-주의사항" tabindex="-1">1. 주의사항 <a class="header-anchor" href="#_1-주의사항" aria-label="Permalink to &quot;1. 주의사항&quot;">​</a></h2><h3 id="robots-txt의-개념과-경로" tabindex="-1">Robots.txt의 개념과 경로 <a class="header-anchor" href="#robots-txt의-개념과-경로" aria-label="Permalink to &quot;Robots.txt의 개념과 경로&quot;">​</a></h3><ul><li><p><strong>정의</strong>: 웹사이트 소유자가 검색 엔진 로봇이나 크롤러 같은 자동화 프로그램에게 &quot;이 시스템의 특정 경로에는 접근해도 된다/안 된다&quot;를 알려주는 일종의 규약 문서</p></li><li><p><strong>경로</strong>: 루트 디렉토리에 배치하는 것이 표준이므로, 도메인 뒤에 <code>/robots.txt</code>를 붙여 확인</p></li></ul><p><strong>지정어(Directive) 상세 분석</strong><br> 네이버의 예시 코드<br><a href="https://www.naver.com/robots.txt" target="_blank" rel="noreferrer">https://www.naver.com/robots.txt</a></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User-agent: *</span></span>
<span class="line"><span>Disallow: /</span></span>
<span class="line"><span>Allow : /$</span></span>
<span class="line"><span>Allow : /.well-known/privacy-sandbox-attestations.json</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><ul><li><p><strong>User-agent</strong>: 크롤링을 수행하는 프로그램(봇)의 이름을 지정</p><ul><li>가령 <code>*</code> (애스터리스크)는 모든 웹 크롤러를 대상으로 동일한 규칙을 적용하겠다는 의미</li></ul></li><li><p><strong>Disallow: /</strong>: 웹사이트의 루트(<code>/</code>) 이하 모든 하위 경로에 대한 크롤링을 기본적으로 금지(Disallow)한다는 선언</p></li><li><p>Allow: 모든 경로를 막았으나, 메인 페이지(<code>/$</code>에서 <code>$</code>는 정규표현식으로 &#39;끝&#39;을 의미하므로 정확히 메인 URL 자체)만은 예외적으로 수집을 허용한다는 의미</p></li><li><p><strong>Allow: /.well-known/...</strong>: 특정 인증 또는 개인정보 보호 규격 관련 파일이 위치한 경로만 추가로 예외 허용함을 의미</p></li></ul><h3 id="수집-및-관리-시-핵심-주의-사항" tabindex="-1">수집 및 관리 시 핵심 주의 사항 <a class="header-anchor" href="#수집-및-관리-시-핵심-주의-사항" aria-label="Permalink to &quot;수집 및 관리 시 핵심 주의 사항&quot;">​</a></h3><ul><li><p><strong>서버 과부하 방지 (Rate Limiting)</strong></p><ul><li>단시간 내의 대량 요청은 웹 서버에 DDoS 공격과 유사한 부하를 주어 IP 차단을 유발할 수 있음</li><li>지연 시간을 요청 사이에 강제 삽입하여 서버를 보호해야 함</li></ul></li><li><p><strong>데이터 관리 및 법적 준수 (Compliance)</strong></p><ul><li>공개된 웹페이지라 하더라도 작성자의 이름, 전화번호, 이메일, 학번 등의 개인정보를 대량으로 수집·저장·유포하는 행위는 개인정보 보호법 위반 소지가 있음</li><li>수집 데이터는 목적 달성 후 안전하게 파기하거나, 식별할 수 없도록 비식별화 처리를 해야 함</li></ul></li></ul><h2 id="_2-웹-크롤링-vs-웹-스크래핑" tabindex="-1">2. 웹 크롤링 vs 웹 스크래핑 <a class="header-anchor" href="#_2-웹-크롤링-vs-웹-스크래핑" aria-label="Permalink to &quot;2. 웹 크롤링 vs 웹 스크래핑&quot;">​</a></h2><p>인터넷에서 자동으로 데이터를 수집하는 방식</p><ul><li><p><strong>웹 크롤링 (Crawling)</strong>:<br>  웹 사이트를 순회하면서 대규모의 데이터를 수집하는 과정</p><ul><li><strong>목적</strong>: 웹사이트의 전체 구조를 파악하고 대규모 데이터를 수집하여 색인(Index)화.</li><li><strong>특징</strong>: 검색엔진(구글, 네이버 등)의 &#39;봇/스파이더&#39;가 링크를 타고 돌아다니며 웹 페이지 간의 관계를 맵핑하고 DB에 저장하는 방식.</li></ul></li><li><p><strong>웹 스크래핑 (Scraping)</strong><br> 특정 웹 페이지에서 필요한 데이터를 추출하는 과정</p><ul><li><strong>목적</strong>: 특정 웹페이지에서 우리가 원하는 <strong>특정 정보만 추출</strong>.</li></ul></li></ul><p>웹 크롤링이 대규모로 웹 사이트의 모든 정보를 가져와 많은 양의 데이터와 링크를 처리한다면, 웹 스크래핑은 보다 특정적이고, 필요한 데이터만을 추출</p><h3 id="_2-정적-웹페이지-vs-동적-웹페이지" tabindex="-1">2. 정적 웹페이지 vs 동적 웹페이지 <a class="header-anchor" href="#_2-정적-웹페이지-vs-동적-웹페이지" aria-label="Permalink to &quot;2. 정적 웹페이지 vs 동적 웹페이지&quot;">​</a></h3><p>데이터를 처리하고 화면에 보여주는 방식의 차이로 인해 수집 접근법이 완전히 달라집니다.</p><ul><li><p><strong>정적 웹페이지 (Static)</strong></p><ul><li><p><strong>동작</strong>: 서버에 미리 저장된 HTML 파일을 그대로 사용자에게 전달. 모든 사용자가 상호작용 없이 동일한 화면을 봄.</p></li><li><p><strong>장단점</strong>: 로딩이 빠르고 서버 부하가 적으나, 실시간 업데이트나 사용자 맞춤형 서비스가 어려움.</p></li><li><p><strong>데이터 추출</strong>: <strong>페이지 소스코드</strong> 내에 수집하려는 실데이터가 텍스트 형태로 그대로 포함되어 있어 직접 읽기 가능.</p></li></ul></li><li><p><strong>동적 웹페이지 (Dynamic)</strong></p><ul><li><p><strong>동작</strong>: 사용자의 요청이나 입력에 따라 서버 사이드 스크립트 또는 클라이언트 사이드 스크립트(JavaScript)가 실시간으로 콘텐츠를 생성 및 업데이트.</p></li><li><p><strong>장단점</strong>: 사용자 맞춤형 콘텐츠 제공 및 실시간 상호작용이 가능하나, 로딩 시간이 더 걸리고 서버 부하가 큼.</p></li><li><p><strong>데이터 추출</strong>: 초기 소스코드만으로는 데이터를 볼 수 없는 경우가 많음. 자바스크립트가 실행되면서 데이터를 로드하는 과정을 포착해야 함.</p></li></ul></li></ul><h3 id="_3-스크래핑-핵심-도구-및-개념" tabindex="-1">3. 스크래핑 핵심 도구 및 개념 <a class="header-anchor" href="#_3-스크래핑-핵심-도구-및-개념" aria-label="Permalink to &quot;3. 스크래핑 핵심 도구 및 개념&quot;">​</a></h3><ul><li><strong>파싱 (Parsing)</strong>: 가공되지 않은 HTML/XML 문서 덩어리를 컴퓨터가 분석하기 쉬운 형태로 분해하고 변환하여 원하는 태그나 속성을 쉽게 찾도록 만드는 작업.</li></ul><table tabindex="0"><thead><tr><th><strong>도구</strong></th><th><strong>주요 타겟</strong></th><th><strong>작동 방식 및 특징</strong></th></tr></thead><tbody><tr><td><strong>BeautifulSoup</strong></td><td>정적 웹페이지</td><td>- HTML/XML 파싱 전문 라이브러리.<br><br> <br><br>- 가져온 웹페이지 소스코드에서 원하는 데이터가 들어있는 태그를 신속하게 탐색 및 추출.</td></tr><tr><td><strong>Selenium</strong></td><td>동적 웹페이지</td><td>- 웹 브라우저 자동화/제어 도구.<br><br> <br><br>- 마우스 클릭, 키보드 입력, 스크롤 등 사람의 행동을 코드로 자동화하여 자바스크립트가 실행된 최종 화면의 동적 데이터를 포착.</td></tr></tbody></table>`,18)])])}const h=l(o,[["render",e]]);export{u as __pageData,h as default};
